using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class BeachUpgradeVerify{static BeachUpgradeVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("BeachUpgradeVerify.request"))return;File.Delete("BeachUpgradeVerify.request");var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=s.GetRootGameObjects().Single(g=>g.name=="South Coast Beach Details");var lods=root.GetComponentsInChildren<LODGroup>();int palms=lods.Count(l=>l.name.Contains("Palm")),rocks=lods.Count(l=>l.name.Contains("Boulder")),groups=lods.Count(l=>l.name.Contains("Colorful"));var group=lods.First(l=>l.name.Contains("Colorful"));var p=group.transform.position;var cap=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);group.ForceLOD(0);cap.Invoke(null,new object[]{s,p+new Vector3(-8,5,-8),p+Vector3.up*1.5f,"Colorful-Beach-Furniture-Near"});group.ForceLOD(1);cap.Invoke(null,new object[]{s,p+new Vector3(-8,5,-8),p+Vector3.up*1.5f,"Colorful-Beach-Furniture-Far-Check"});group.ForceLOD(-1);int near=group.GetLODs()[0].renderers.Sum(r=>r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3),far=group.GetLODs()[1].renderers.Sum(r=>r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3);EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.AppendAllText("FinalEnvironmentRoadReview/BeachDetailUpgrade.txt","\nVERIFY actual palms="+palms+" rocks="+rocks+" colorful furniture groups="+groups+"; near/far LOD groups="+lods.Count(l=>l.lodCount==2)+"; furniture near/far triangles="+near+"/"+far+"; forced near/far previews checked and automatic LOD restored; scene saved.");}}
